using System;using System.IO;using System.IO.Pipes;using System.Security;using System.Security.AccessControl;using System.Security.Principal;using System.Security.Cryptography;using System.Text;using System.Diagnostics;using System.Web.Script.Serialization;using System.Linq;using System.Collections.Generic;
public sealed class SetupRequest {public string Home,Root,Steam,IssuerSID,User,Pipe;}
public static class SetupService {
 public static string SuggestedRoot{get{foreach(string name in new[]{"account.json","setup-journal.json"})try{string file=Path.Combine(Engine.Home,@"Data\Native",name);if(!File.Exists(file))continue;var value=new JavaScriptSerializer().Deserialize<Dictionary<string,object>>(File.ReadAllText(file));if(Convert.ToString(value["IssuerSID"])!=WindowsIdentity.GetCurrent().User.Value)continue;return name=="account.json"?Path.GetDirectoryName(Convert.ToString(value["Profile"])):Convert.ToString(value["Root"]);}catch{}return Path.Combine(Engine.Home,@"Profiles\Second");}}
 static bool CanResume(string root){foreach(string name in new[]{"account.json","setup-journal.json"})try{string file=Path.Combine(Engine.Home,@"Data\Native",name);if(!File.Exists(file))continue;var value=new JavaScriptSerializer().Deserialize<Dictionary<string,object>>(File.ReadAllText(file));if(Convert.ToString(value["IssuerSID"])!=WindowsIdentity.GetCurrent().User.Value)continue;string recorded=name=="account.json"?Path.GetDirectoryName(Convert.ToString(value["Profile"])):Convert.ToString(value["Root"]);if(Path.GetFullPath(recorded).TrimEnd('\\').Equals(root,StringComparison.OrdinalIgnoreCase))return true;}catch{}return false;}
 static void Finish(string steam,string root){Engine.Current=new Settings{Schema=2,MainSteam=steam,NativeRoot=root,ProfileRoot=Path.Combine(root,"Windows Profile"),SecondSteam=Path.Combine(root,@"Client\steam.exe")};Engine.Setup(steam);LibraryCatalog.Sync(Engine.Current);Engine.EnsureBroker();}
 static void ClearUnusedCredential(string credential,string user){try{new NTAccount(Environment.MachineName,user).Translate(typeof(SecurityIdentifier));}catch(IdentityNotMappedException){File.Delete(credential);}}
 public static void Validate(string steam,string root){root=Path.GetFullPath(root).TrimEnd('\\');var drive=new DriveInfo(Path.GetPathRoot(root));if(!drive.IsReady||!drive.DriveFormat.Equals("NTFS",StringComparison.OrdinalIgnoreCase))throw new IOException("Choose a folder on an available NTFS drive for the Windows profile.");string main=Path.GetDirectoryName(Path.GetFullPath(steam));if(!File.Exists(steam)||!Path.GetFileName(steam).Equals("steam.exe",StringComparison.OrdinalIgnoreCase))throw new IOException("Select an installed steam.exe.");if(root.Length<=3||root.StartsWith(@"\\")||root.Equals(main,StringComparison.OrdinalIgnoreCase)||main.StartsWith(root+"\\",StringComparison.OrdinalIgnoreCase)||root.StartsWith(main+"\\",StringComparison.OrdinalIgnoreCase)||root.Equals(Engine.Home,StringComparison.OrdinalIgnoreCase)||Engine.Home.StartsWith(root+"\\",StringComparison.OrdinalIgnoreCase))throw new IOException("Choose a separate local folder for Second Steam, outside the main Steam installation.");for(string p=root;!String.IsNullOrEmpty(p);p=Path.GetDirectoryName(p))if((Directory.Exists(p)||File.Exists(p))&&(File.GetAttributes(p)&FileAttributes.ReparsePoint)!=0)throw new IOException("Use a real folder, not a symbolic link or junction.");if(Directory.Exists(root)&&Directory.GetFileSystemEntries(root).Length>0&&!CanResume(root))throw new IOException("Choose an empty folder for first-time setup. Existing data will not be overwritten.");}
 public static void Provision(string steam,string root){
  RemovalService.RequireComplete();
  RuntimeAuthorization.Require(Engine.Home);
  Validate(steam,root);string state=Path.Combine(Engine.Home,@"Data\Native");Directory.CreateDirectory(state);var issuer=WindowsIdentity.GetCurrent().User;var acl=new DirectorySecurity();acl.SetAccessRuleProtection(true,false);foreach(string sid in new[]{issuer.Value,"S-1-5-18","S-1-5-32-544"})acl.AddAccessRule(new FileSystemAccessRule(new SecurityIdentifier(sid),FileSystemRights.FullControl,InheritanceFlags.ContainerInherit|InheritanceFlags.ObjectInherit,PropagationFlags.None,AccessControlType.Allow));Directory.SetAccessControl(state,acl);
  string credential=Path.Combine(state,"password.dpapi");bool resuming=File.Exists(credential);if(File.Exists(Path.Combine(state,"account.json"))){var saved=new JavaScriptSerializer().Deserialize<NativeAccount>(File.ReadAllText(Path.Combine(state,"account.json")));if(saved.IssuerSID!=issuer.Value||saved.Profile!=Path.Combine(Path.GetFullPath(root).TrimEnd('\\'),"Windows Profile")||((SecurityIdentifier)new NTAccount(Environment.MachineName,saved.User).Translate(typeof(SecurityIdentifier))).Value!=saved.SID)throw new IOException("The saved Windows account does not match this setup. It has not been changed.");Finish(Path.GetFullPath(steam),Path.GetFullPath(root).TrimEnd('\\'));return;}if(resuming&&!CanResume(Path.GetFullPath(root).TrimEnd('\\')))throw new IOException("Existing setup credentials do not match this folder. They have been preserved.");
  string password;if(resuming){string hex=File.ReadAllText(credential).Trim();byte[] bytes=Enumerable.Range(0,hex.Length/2).Select(i=>Convert.ToByte(hex.Substring(i*2,2),16)).ToArray();password=Encoding.Unicode.GetString(ProtectedData.Unprotect(bytes,null,DataProtectionScope.CurrentUser));}else{byte[] random=new byte[36];using(var rng=RandomNumberGenerator.Create())rng.GetBytes(random);password=Convert.ToBase64String(random)+"aA1!";byte[] protectedBytes=ProtectedData.Protect(Encoding.Unicode.GetBytes(password),null,DataProtectionScope.CurrentUser);File.WriteAllText(credential,BitConverter.ToString(protectedBytes).Replace("-",""));Array.Clear(random,0,random.Length);}
  var request=new SetupRequest{Home=Engine.Home,Root=Path.GetFullPath(root).TrimEnd('\\'),Steam=Path.GetFullPath(steam),IssuerSID=issuer.Value,User="DualSteam_"+BitConverter.ToString(SHA256.Create().ComputeHash(Encoding.UTF8.GetBytes(issuer.Value+Path.GetFullPath(root).TrimEnd('\\').ToLowerInvariant()))).Replace("-","").Substring(0,8).ToLowerInvariant(),Pipe="DualSteamSetup_"+Guid.NewGuid().ToString("N")};string file=Path.Combine(state,"setup-request.json");File.WriteAllText(file,new JavaScriptSerializer().Serialize(request));
  var security=new PipeSecurity();security.SetAccessRuleProtection(true,false);security.AddAccessRule(new PipeAccessRule(issuer,PipeAccessRights.FullControl,AccessControlType.Allow));security.AddAccessRule(new PipeAccessRule(new SecurityIdentifier("S-1-5-32-544"),PipeAccessRights.ReadWrite,AccessControlType.Allow));security.AddAccessRule(new PipeAccessRule(new SecurityIdentifier("S-1-5-18"),PipeAccessRights.FullControl,AccessControlType.Allow));
  using(var pipe=new NamedPipeServerStream(request.Pipe,PipeDirection.Out,1,PipeTransmissionMode.Byte,PipeOptions.Asynchronous,4096,4096,security)){
   var start=new ProcessStartInfo(Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.System),@"WindowsPowerShell\v1.0\powershell.exe"),"-NoProfile -ExecutionPolicy Bypass -File "+Engine.Quote(Path.Combine(Engine.Home,@"Source\Setup-Elevated.ps1"))+" -Request "+Engine.Quote(file)){UseShellExecute=true,Verb="runas",WindowStyle=ProcessWindowStyle.Hidden};Process process;
   try{process=Process.Start(start);}catch{if(!resuming)File.Delete(credential);throw;}
   using(process){var connected=pipe.WaitForConnectionAsync();var timeout=Stopwatch.StartNew();while(!connected.Wait(250)){if(timeout.Elapsed.TotalMinutes>3)throw new IOException("Setup did not connect within three minutes. Close the setup prompt before retrying.");if(process.HasExited){if(!resuming)ClearUnusedCredential(credential,request.User);throw new IOException("Setup stopped before receiving its secure credential. Check Data/Native/setup-result.json.");}}using(var writer=new StreamWriter(pipe,Encoding.UTF8,4096,true){AutoFlush=true})writer.WriteLine(password);password=null;if(!process.WaitForExit(180000))throw new IOException("Setup is still running. Wait for it to finish before starting setup again.");if(process.ExitCode!=0){try{new NTAccount(Environment.MachineName,request.User).Translate(typeof(SecurityIdentifier));}catch(IdentityNotMappedException){File.Delete(credential);}string detail="Check Data/Native/setup-result.json before retrying.";string result=Path.Combine(state,"setup-result.json");if(File.Exists(result)){var failure=new JavaScriptSerializer().Deserialize<System.Collections.Generic.Dictionary<string,object>>(File.ReadAllText(result));if(failure.ContainsKey("Error"))detail=Convert.ToString(failure["Error"]);}throw new IOException("Setup could not finish. Main Steam was not changed. "+detail);}}
  }
  Finish(request.Steam,request.Root);
 }
}
